CREATE TABLE semio_video_document (id INTEGER PRIMARY KEY, schema TEXT NOT NULL);
CREATE TABLE semio_video_stream (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES semio_video_document(id), ordinal INTEGER NOT NULL CHECK (ordinal >= 0), kind TEXT NOT NULL CHECK (kind IN ('video','audio','subtitle')), codec TEXT NOT NULL, width INTEGER NOT NULL CHECK (width BETWEEN 0 AND 4294967295), height INTEGER NOT NULL CHECK (height BETWEEN 0 AND 4294967295), rate_numerator INTEGER NOT NULL, rate_denominator INTEGER NOT NULL CHECK (rate_denominator <> 0));
CREATE TABLE semio_video_sample (id INTEGER PRIMARY KEY, stream_id INTEGER NOT NULL REFERENCES semio_video_stream(id), ordinal INTEGER NOT NULL CHECK (ordinal >= 0), presentation_timestamp TEXT NOT NULL, key_frame INTEGER NOT NULL CHECK (key_frame IN (0,1)), data BLOB NOT NULL);
